export function searchTenThousandNodes(q = "") {
  const s = q.trim().toLowerCase();
  if (!s) return TEN_THOUSAND_NODES.slice(0, 24);
  return TEN_THOUSAND_NODES.filter((n) => n.name.toLowerCase().includes(s) || n.id.toLowerCase().includes(s) || n.sector.toLowerCase().includes(s)).slice(0, 40);
}
